import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Toggle","description":"","frontmatter":{},"headers":[],"relativePath":"components/toggle.md","filePath":"components/toggle.md"}'),i={name:"components/toggle.md"};function s(h,t,n,r,c,l){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="toggle" tabindex="-1">Toggle <a class="header-anchor" href="#toggle" aria-label="Permalink to &quot;Toggle&quot;">​</a></h1><p>Toggle is a switch for a setting that takes effect at once.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it when the change applies without a separate save. A choice that is saved with a form is a <a href="./checkbox">Checkbox</a>. <code>between</code> puts the text on the left and the switch at the right end, for a row of settings; <code>indent</code> places a switch under the one it depends on.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>checked</code></td><td><code>false</code></td><td>The state (bindable)</td></tr><tr><td><code>label</code></td><td></td><td>The text beside the switch, which is its name</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name when there is no text</td></tr><tr><td><code>between</code></td><td><code>false</code></td><td>The text on the left, the switch at the right end</td></tr><tr><td><code>indent</code></td><td><code>false</code></td><td>Under a parent switch: indented by pad-md</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be changed</td></tr><tr><td><code>id</code></td><td></td><td>The id of the input</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the new state</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The control is as high as a small button (<code>--kata-height-button-sm</code>), and the whole of it is pressed, text included. The switch is a native checkbox with <code>role=&quot;switch&quot;</code>, as wide as a button&#39;s height and as high as a badge; its knob sits on the left when off and on the right, on the solid surface, when on. The text is gap-sm from the switch and trimmed to its ink. A long text wraps instead of being cut: the control grows downwards, and the switch stays level with the first line, centred in the height of a small button as one line is. In a container without padding it takes the inset of the list items at its sides. Disabled, the text and a switch that is off are dimmed; a switch that is on takes the solid-disabled surface with its text for the knob, not dimmed.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/toggle/" title="Toggle" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/toggle/" target="_blank" rel="noopener">Toggle</a></figcaption></figure>',10)])])}const f=e(i,[["render",s]]);export{p as __pageData,f as default};
